parameters.text:
=Analyze the client's request and identify what they want to build.

Client name: {{ $json.client_name }}

Company: {{ $json.company }}

Request: {{ $json.request }}

Do not evaluate the client's budget.
Do not determine qualification or priority based on budget.

request_type must be a short label of 2-4 words (for example: "AI chatbot", "CRM integration", "Telegram bot"), not a sentence.

Return the result using the required structured output format.

parameters.jsonSchemaExample:
{
  "request_type": "AI chatbot",
  "reason": "The client wants a chatbot that can answer customer questions and qualify leads."
}

assignments.value:
=
{{ (() => {
  const name = String($json.name ?? '').trim();
  const company = String($json.company ?? '').trim();
  const budget = String($json.budget ?? '').trim();
  const request = String($json.request ?? '').trim();

  let reason = 'Invalid lead data';

  if (budget === '' || !Number.isFinite(Number(budget)) || Number(budget) < 0) {
    reason = 'Invalid budget value';
  } else if (name === '') {
    reason = 'Client name is missing';
  } else if (company === '') {
    reason = 'Company name is missing';
  } else if (request === '') {
    reason = 'Request description is missing';
  }

  return [
    '⚠️ Invalid lead received',
    'Client: ' + (name || 'Not provided'),
    'Company: ' + (company || 'Not provided'),
    'Budget: ' + (budget || 'Not provided'),
    'Reason: ' + reason
  ].join('\n');
})() }}

conditions.leftValue:
={{ (() => {
  const budget = Number(
    $('Retry Input Data').isExecuted
      ? $('Retry Input Data').first().json.budget
      : $('Convert Budget').first().json.budget
  );

  return budget < 1000 ? 'low' : budget <= 3000 ? 'medium' : 'high';
})() }}

